package Program.service; import Program.model.Budget; import Program.utils.FileManager; import java.util.*;
public class BudgetService { public List<Budget> load(String user){return FileManager.read("budgets.txt").stream().map(this::parse).filter(Objects::nonNull).filter(b->b.getUserId().equals(user)).toList();} private Budget parse(String s){try{String[] p=s.split("\\|",-1);return p.length==4?new Budget(p[0],p[1],p[2],Double.parseDouble(p[3])):null;}catch(Exception e){return null;}} private String record(Budget b){return String.join("|",b.getId(),b.getUserId(),FileManager.clean(b.getCategory()),String.valueOf(b.getLimit()));} public Budget add(String user,String cat,double limit){Budget b=new Budget(UUID.randomUUID().toString(),user,cat,limit);FileManager.append("budgets.txt",record(b));return b;} public void update(Budget b,String cat,double limit){b.setCategory(cat);b.setLimit(limit);FileManager.update("budgets.txt",s->s.startsWith(b.getId()+"|"),record(b));} public void delete(String id){FileManager.delete("budgets.txt",s->s.startsWith(id+"|"));} public void apply(String user,Map<String,Double> values){for(Budget b:load(user)){if(values.containsKey(b.getCategory()))update(b,b.getCategory(),values.remove(b.getCategory()));}values.forEach((cat,limit)->add(user,cat,limit));}}
